<?php
declare(strict_types=1);
final class LivedoorAdapter implements PlatformAdapter{
 public function key():string{return'livedoor';}
 public function validate(array $a):array{$c=json_decode((string)($a['platform_config']??'{}'),true)?:[];$u=rtrim((string)($c['atompub_url']??''),'/');$ok=(bool)preg_match('#^https://livedoor\.blogcms\.jp/atompub/[^/]+$#',$u)&&!empty($c['livedoor_id'])&&!empty($c['api_password']);return['ok'=>$ok,'message'=>$ok?'設定済み':'AtomPub URL / livedoor ID / APIパスワードを設定してください'];}
 public function publish(array $a,array $p):array{$c=json_decode((string)($a['platform_config']??'{}'),true)?:[];$v=$this->validate($a);if(!$v['ok'])throw new RuntimeException($v['message']);$entry='<?xml version="1.0" encoding="utf-8"?><entry xmlns="http://www.w3.org/2005/Atom"><title>'.htmlspecialchars((string)$p['title'],ENT_XML1|ENT_QUOTES,'UTF-8').'</title><content type="html">'.htmlspecialchars((string)$p['html'],ENT_XML1|ENT_QUOTES,'UTF-8').'</content><updated>'.date('c').'</updated></entry>';$url=rtrim($c['atompub_url'],'/').'/article';$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$entry,CURLOPT_TIMEOUT=>20,CURLOPT_HTTPHEADER=>['Content-Type: application/atom+xml;type=entry; charset=utf-8','Authorization: Basic '.base64_encode($c['livedoor_id'].':'.$c['api_password']),'Expect:']]);$body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$err=curl_error($ch);curl_close($ch);if($body===false||$status<200||$status>=300)throw new RuntimeException('Livedoor投稿失敗 HTTP '.$status.' '.$err);return['ok'=>true,'status'=>$status,'response'=>$body];}
}
